import 'dart:convert';import 'package:archive/archive.dart';import 'package:flutter_test/flutter_test.dart';import 'package:studygram/features/upload/parser.dart';import 'package:syncfusion_flutter_pdf/pdf.dart';void main(){group('StudyParser',(){test('splits Markdown into sections',(){final d=StudyParser.parseText('# Thermodynamics\n\nHeat transfer.\n\n## Entropy\n\nState function.','notes.md');expect(d.sections.length,greaterThanOrEqualTo(2));expect(d.sections.first,contains('Thermodynamics'));expect(d.sections.last,contains('Entropy'));});test('empty text fallback',()=>expect(StudyParser.parseText('','empty.txt').sections,['No text content found.']));test('PPTX slide XML extraction',(){final a=Archive();final x=utf8.encode('<p:sld xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:t>Slide title</a:t><a:t>Bullet point</a:t></p:sld>');a.addFile(ArchiveFile('ppt/slides/slide1.xml',x.length,x));final d=StudyParser.parsePptx(ZipEncoder().encode(a)!, 'lecture.pptx');expect(d.sections.single,contains('Slide title'));expect(d.sections.single,contains('Bullet point'));});test('PDF text extraction',(){final p=PdfDocument();p.pages.add().graphics.drawString('Offline PDF text',PdfStandardFont(PdfFontFamily.helvetica,12));final b=p.saveSync();p.dispose();expect(StudyParser.parsePdf(b,'handout.pdf').sections.single,contains('Offline PDF text'));});test('normalizes broken words and wrapped lines',()=>expect(StudyParser.normalizeExtractedText('inter-\n national\nwrapped text\ncontinues\n\n\nEnd'),'international wrapped text continues\n\nEnd'));});}